begin;
-- Confirmado pela usuária: trimestre anterior e dias efetivos identificados no estoque.
-- 01.11 aplicado somente às versões trimestrais; nenhuma tabela/versão histórica do OOR é alterada.
create temporary table quarter_calculation(code text,sku text,name text,unit text,avg_qty numeric,avg_hl numeric,avg_pallets numeric,max_qty numeric,max_hl numeric,max_days numeric,flags jsonb) on commit drop;
-- Universo da política = produtos com vendas na base trimestral, sem ativos de giro.
-- Produtos fora dessa base ficam documentados no audit log, sem serem tratados como venda desconhecida ou inventados.
select v.id,p.sku_code,'GENERATE',jsonb_build_object('reason','FORA_DA_BASE_DE_VENDAS_TRIMESTRAL','previous_item',to_jsonb(p),'history_preserved',true)
from stock_policy_items p join stock_policy_versions v on v.id=p.version_id
where v.code in('T1/2026','T2/2026','T3/2026','T4/2026') and v.status='draft' and v.oor_enabled=false
and not exists(select 1 from quarter_calculation c where c.code=v.code and c.sku=p.sku_code);
delete from stock_policy_items p using stock_policy_versions v
where p.version_id=v.id and v.code in('T1/2026','T2/2026','T3/2026','T4/2026') and v.status='draft' and v.oor_enabled=false
and not exists(select 1 from quarter_calculation c where c.code=v.code and c.sku=p.sku_code);
update stock_policy_items p set sku_name=c.name,unit_code=c.unit,avg_daily_qty=c.avg_qty,
 avg_daily_boxes=case when c.unit='cx' then c.avg_qty end,avg_daily_hl=c.avg_hl,avg_daily_pallets=c.avg_pallets,
 min_qty=c.avg_qty*3,objective_qty=c.avg_qty*5,min_hl=c.avg_hl*3,objective_hl=c.avg_hl*5,
 max_qty=c.max_qty,max_hl=c.max_hl,max_days=c.max_days,out_qty=c.avg_qty*3,over_qty=c.max_qty,
 review_flags=c.flags,review_note=null,policy_source='TRIMESTRAL_ESTOQUE_DIAS_0111',
 suggestion_basis='Trimestre anterior. Média = vendas / dias de estoque (76, 75, 74 e 78). Mínimo 3 dias, objetivo 5 dias. Máximo = estoque médio disponível + puxada acumulada, na mesma unidade. Litros convertidos para HL por /100. Estoque em caixas convertido de volta para Dz quando a venda está em Dz. Ativos de giro e produtos fora da base de vendas não participam. 01.11 atualizado aplicado somente à política trimestral.',
 updated_at=now()
from stock_policy_versions v,quarter_calculation c
where p.version_id=v.id and v.code=c.code and p.sku_code=c.sku and v.status='draft' and v.oor_enabled=false;
update stock_policy_versions v set calculation_metadata=v.calculation_metadata||jsonb_build_object(
 'days_worked',case v.code when 'T1/2026' then 76 when 'T2/2026' then 75 when 'T3/2026' then 74 else 78 end,
 'stock_days',case v.code when 'T1/2026' then 76 when 'T2/2026' then 75 when 'T3/2026' then 74 else 78 end,
 'days_source','COUNT DISTINCT reference_date no estoque do trimestre anterior',
 'sales_period_confirmed',true,'catalog_source','r_PW01084C_Gabrielypi_08205046.csv.inf',
 'asset_exclusion_confirmed',true,'universe','Produtos com vendas na base trimestral, sem ativos de giro',
 'items',(select count(*) from stock_policy_items p where p.version_id=v.id),
 'demand_items',(select count(*) from stock_policy_items p where p.version_id=v.id and p.avg_daily_qty>0),
 'pending_maximum_items',(select count(*) from stock_policy_items p where p.version_id=v.id and p.max_qty is null),
 'readiness',case when v.code='T1/2026' then 'ready' else 'partial' end,
 'missing',case when v.code='T1/2026' then '[]'::jsonb else jsonb_build_array('02.05.01 completo do trimestre-base') end
),method_version='quarterly-stock-days-0111-v2',notes=null,updated_at=now()
where v.code in('T1/2026','T2/2026','T3/2026','T4/2026') and v.status='draft' and v.oor_enabled=false;
select id,'GENERATE',jsonb_build_object('method','quarterly-stock-days-0111-v2','history_preserved',true,'readiness',calculation_metadata->'readiness','catalog_source','r_PW01084C_Gabrielypi_08205046.csv.inf','user_confirmed_previous_3_months',true)
from stock_policy_versions where code in('T1/2026','T2/2026','T3/2026','T4/2026') and status='draft' and oor_enabled=false;
commit;
